const items = $input.all();
const { data, html } = items[0].json;

if (!html || !Array.isArray(data) || data.length === 0) {
  return [{ json: { data, html } }];
}

// Find all {{{token}}} inside select-field class divs
const selectFieldRegex = /select-field[^>]*>[\s\S]*?\{\{\{([a-zA-Z0-9_]+)\}\}\}/g;
const selectTemplates = [];
let match;
while ((match = selectFieldRegex.exec(html)) !== null) {
  selectTemplates.push(match[1]);
}

if (selectTemplates.length === 0) {
  return [{ json: { data, html } }];
}

const record = data[0];

for (const templateName of selectTemplates) {
  // Strip f_ prefix — form templates reference f_*_dd but base templates use *_dd
  const baseTemplateName = templateName.startsWith('f_') ? templateName.slice(2) : templateName;

  const hydrateResult = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://n8n.whatsfresh.app/webhook/hydrate-guide',
    body: {
      template_name: baseTemplateName,
      source: 'wf-server',
      format: 'html'
    },
    json: true
  });

  let selectHtml = '';
  if (typeof hydrateResult === 'string') {
    selectHtml = hydrateResult;
  } else if (hydrateResult?.html) {
    selectHtml = hydrateResult.html;
  } else if (Array.isArray(hydrateResult) && hydrateResult[0]?.html) {
    selectHtml = hydrateResult[0].html;
  }

  // Store under original token name so template replacement works
  record[templateName] = selectHtml;
}

return [{ json: { data: [record], html } }];
